package com.ruoyi.web.biz;
import java.util.*;
import java.time.*;
import java.math.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.common.exception.ServiceException;
@Service
public class ExecutionService {
 final JdbcTemplate db;final EmployeeService users;final TaskService tasks;
 static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
 public ExecutionService(CompanyOnboardingMapper m,EmployeeService u,TaskService tasks){db=m.database();users=u;this.tasks=tasks;}
 long uid(){return SecurityUtils.getUserId();}
 void perm(String op){if(!users.hasPermission("biz:execution:"+op))throw new AccessDeniedException("无项目执行权限");}
 long own(String op){perm(op);Long c=users.userCompany(uid());if(c==null)throw new AccessDeniedException("无有效企业归属");if(op.equals("manage")&&!users.hasRole(uid(),"company_admin")&&!users.hasRole(uid(),"company_business"))throw new AccessDeniedException("仅企业管理员或业务岗可管理执行");return c;}
 long read(Long requested){perm("read");if(uid()==1||users.hasRole(uid(),"platform_admin")){if(requested==null)throw new ServiceException("请选择企业",400);return requested;}long c=own("read");if(requested!=null&&requested!=c)throw new AccessDeniedException("不能查询其他企业");return c;}
 void lock(long c){if(db.queryForList("SELECT id FROM biz_company WHERE id=? AND status='ACTIVE' FOR UPDATE",c).isEmpty())throw new AccessDeniedException("企业无效");}
 void activeUser(long c,long user){if(db.queryForList("SELECT u.user_id FROM sys_user u JOIN biz_company_user m ON m.user_id=u.user_id JOIN biz_employee_info e ON e.company_id=m.company_id AND e.user_id=u.user_id WHERE u.user_id=? AND m.company_id=? AND u.status='0' AND u.del_flag='0' AND m.status='ACTIVE' AND e.status='ACTIVE' FOR UPDATE",user,c).isEmpty())throw new AccessDeniedException("员工不属于本企业或已离职");}
 void amount(BigDecimal q){if(q==null||q.signum()<=0||q.scale()>2||q.compareTo(new BigDecimal("9999999999999999.99"))>0)throw new ServiceException("工作量须为正数且最多两位小数",400);}
 void note(String text){if(text==null||text.isBlank()||text.length()>500)throw new ServiceException("操作意见必填且最多500字",400);}
 void version(Map<String,Object> row,Integer v){if(v==null||v.intValue()!=((Number)row.get("version")).intValue())throw new ServiceException("版本已变更，请刷新",409);}
 Map<String,Object> project(long c,long id,boolean lock){var rows=db.queryForList("SELECT * FROM biz_project WHERE company_id=? AND id=?"+(lock?" FOR UPDATE":""),c,id);if(rows.isEmpty())throw new ServiceException("项目不存在或无权访问",404);return rows.get(0);}
 void writable(Map<String,Object> p){if(!"ACTIVE".equals(p.get("status")))throw new ServiceException("项目已完成或归档，不允许修改",409);}
 Map<String,Object> assignment(long c,long id,boolean lock){var rows=db.queryForList("SELECT * FROM biz_task_assignment WHERE company_id=? AND id=?"+(lock?" FOR UPDATE":""),c,id);if(rows.isEmpty())throw new ServiceException("分配记录不存在或无权访问",404);if(rows.get(0).get("project_id")==null)throw new ServiceException("历史分配尚未关联项目，请先迁移",409);return rows.get(0);}
 void mine(Map<String,Object> a){if(((Number)a.get("user_id")).longValue()!=uid())throw new AccessDeniedException("只能操作本人分配任务");}
 void event(long c,long p,Long a,Long record,String action,Object before,Object after,String opinion){db.update("INSERT INTO biz_execution_event(company_id,project_id,assignment_id,record_id,action,before_value,after_value,opinion,actor_id) VALUES(?,?,?,?,?,?,?,?,?)",c,p,a,record,action,String.valueOf(before),String.valueOf(after),opinion,uid());}
 BigDecimal sum(List<Map<String,Object>> rows,String column){BigDecimal total=BigDecimal.ZERO;for(var row:rows)total=total.add((BigDecimal)row.get(column));return total;}
 public List<Map<String,Object>> companies(){perm("read");if(uid()==1||users.hasRole(uid(),"platform_admin"))return db.queryForList("SELECT id,company_name FROM biz_company WHERE status='ACTIVE'");long c=own("read");return db.queryForList("SELECT id,company_name FROM biz_company WHERE id=?",c);}
 public List<Map<String,Object>> approved(){long c=own("manage");return db.queryForList("SELECT s.*,t.title,t.unit FROM biz_task_signup s JOIN biz_task t ON t.id=s.task_id WHERE s.company_id=? AND s.status='APPROVED' AND t.status IN ('PUBLISHED','CLOSED','EXECUTING') AND t.start_date IS NOT NULL AND t.end_date IS NOT NULL AND t.target_quantity>0 AND NOT EXISTS(SELECT 1 FROM biz_project_task l WHERE l.company_id=s.company_id AND l.signup_id=s.id) ORDER BY s.id DESC LIMIT 500",c);}
 public List<Map<String,Object>> staff(){long c=own("manage");return db.queryForList("SELECT user_id,real_name FROM biz_employee_info WHERE company_id=? AND status='ACTIVE' ORDER BY id LIMIT 1000",c);}
 @Transactional public long link(long signup,Long existing,String name){long c=own("manage");lock(c);activeUser(c,uid());var rows=db.queryForList("SELECT s.*,t.title,t.unit,t.start_date,t.end_date,t.target_quantity AS task_target,t.unit_price AS task_unit_price,t.price_version AS task_price_version,t.status AS task_status FROM biz_task_signup s JOIN biz_task t ON t.id=s.task_id WHERE s.company_id=? AND s.id=? FOR UPDATE",c,signup);if(rows.isEmpty())throw new ServiceException("报名不存在或无权访问",404);var s=rows.get(0);if(s.get("start_date")==null||s.get("end_date")==null||((BigDecimal)s.get("task_target")).signum()<=0)throw new ServiceException("历史任务缺少有效日期或目标量，请先迁移完善",409);if(!"APPROVED".equals(s.get("status"))||!Set.of("PUBLISHED","CLOSED","EXECUTING").contains(s.get("task_status")))throw new ServiceException("任务或报名状态不可执行",409);if(!db.queryForList("SELECT id FROM biz_project_task WHERE company_id=? AND signup_id=? FOR UPDATE",c,signup).isEmpty())throw new ServiceException("报名已关联项目",409);
 long id;if(existing==null){if(name==null||name.isBlank()||name.length()>100)throw new ServiceException("项目名称必填且最多100字",400);String code="PRJ-"+UUID.randomUUID();db.update("INSERT INTO biz_project(company_id,project_code,project_name,owner_user_id,start_date,end_date,status,unit,create_by) VALUES(?,?,?,?,?,?,'ACTIVE',?,?)",c,code,name,uid(),s.get("start_date"),s.get("end_date"),s.get("unit"),SecurityUtils.getUsername());id=db.queryForObject("SELECT id FROM biz_project WHERE company_id=? AND project_code=?",Long.class,c,code);}else{id=existing;var p=project(c,id,true);writable(p);if(!s.get("unit").equals(p.get("unit")))throw new ServiceException("关联项目单位必须一致",400);db.update("UPDATE biz_project SET start_date=LEAST(start_date,?),end_date=GREATEST(end_date,?),version=version+1 WHERE id=? AND company_id=?",s.get("start_date"),s.get("end_date"),id,c);}
 db.update("INSERT INTO biz_project_task(company_id,project_id,signup_id,task_id,target_quantity,unit,unit_price,price_version,price_snapshot_time) VALUES(?,?,?,?,?,?,?,?,?)",c,id,signup,s.get("task_id"),s.get("promised_quantity"),s.get("unit"),s.get("task_unit_price"),s.get("task_unit_price")==null?null:s.get("task_price_version"),s.get("task_unit_price")==null?null:LocalDateTime.now(ZONE));db.update("UPDATE biz_task_signup SET execution_status='EXECUTING',version=version+1 WHERE id=? AND company_id=?",signup,c);event(c,id,null,null,"LINK","",s,"审核通过任务关联项目");return id;}
 public List<Map<String,Object>> projects(Long requested){long c=read(requested);return db.queryForList("SELECT * FROM biz_project WHERE company_id=? ORDER BY id DESC LIMIT 500",c);}
 Map<String,Object> progress(long c,long id,boolean current){var p=project(c,id,current);String lock=current?" FOR UPDATE":"";var links=db.queryForList("SELECT l.*,t.title FROM biz_project_task l JOIN biz_task t ON t.id=l.task_id WHERE l.company_id=? AND l.project_id=?"+lock,c,id);var assignments=db.queryForList("SELECT a.*,e.real_name FROM biz_task_assignment a JOIN biz_employee_info e ON e.company_id=a.company_id AND e.user_id=a.user_id WHERE a.company_id=? AND a.project_id=?"+lock,c,id);var work=db.queryForList("SELECT w.* FROM biz_work_record w JOIN biz_task_assignment a ON a.id=w.assignment_id AND a.company_id=w.company_id WHERE a.company_id=? AND a.project_id=?"+lock,c,id);BigDecimal total=sum(links,"target_quantity"),done=BigDecimal.ZERO;Map<Long,BigDecimal> perUser=new LinkedHashMap<>(),perAssignment=new HashMap<>();for(var w:work)if("CONFIRMED".equals(w.get("status"))){BigDecimal q=(BigDecimal)w.get("quantity");done=done.add(q);long user=((Number)w.get("user_id")).longValue();perUser.merge(user,q,BigDecimal::add);perAssignment.merge(((Number)w.get("assignment_id")).longValue(),q,BigDecimal::add);}List<Map<String,Object>> members=new ArrayList<>();for(var a:assignments){long user=((Number)a.get("user_id")).longValue();a.put("confirmed_quantity",perAssignment.getOrDefault(((Number)a.get("id")).longValue(),BigDecimal.ZERO));}for(var entry:perUser.entrySet())members.add(Map.of("userId",entry.getKey(),"confirmedQuantity",entry.getValue()));
 p.put("links",links);p.put("assignments",assignments);p.put("workRecords",work);p.put("totalQuantity",total);p.put("confirmedQuantity",done);p.put("remainingQuantity",total.subtract(done));p.put("percent",total.signum()==0?BigDecimal.ZERO:done.multiply(new BigDecimal("100")).divide(total,2,RoundingMode.HALF_UP));p.put("members",members);p.put("events",db.queryForList("SELECT * FROM biz_execution_event WHERE company_id=? AND project_id=? ORDER BY id DESC LIMIT 500",c,id));return p;}
 public Map<String,Object> progress(Long requested,long id){return progress(read(requested),id,false);}
 public record Assign(long signupId,long userId,BigDecimal quantity,LocalDate dueDate){}
 @Transactional public long assign(long pid,Assign in){long c=own("manage");lock(c);var p=project(c,pid,true);writable(p);activeUser(c,in.userId());amount(in.quantity());var links=db.queryForList("SELECT l.*,t.start_date,t.end_date FROM biz_project_task l JOIN biz_task t ON t.id=l.task_id WHERE l.company_id=? AND l.project_id=? AND l.signup_id=? FOR UPDATE",c,pid,in.signupId());if(links.isEmpty())throw new ServiceException("报名不属于该项目",404);var l=links.get(0);if(in.dueDate()==null||in.dueDate().isBefore(LocalDate.now(ZONE))||in.dueDate().isBefore(((java.sql.Date)l.get("start_date")).toLocalDate())||in.dueDate().isAfter(((java.sql.Date)l.get("end_date")).toLocalDate()))throw new ServiceException("分配截止日期无效",400);var allocated=db.queryForList("SELECT assigned_quantity FROM biz_task_assignment WHERE company_id=? AND signup_id=? AND status<>'CANCELLED' FOR UPDATE",c,in.signupId());if(sum(allocated,"assigned_quantity").add(in.quantity()).compareTo((BigDecimal)l.get("target_quantity"))>0)throw new ServiceException("分配量超过企业承诺量",409);var previous=db.queryForList("SELECT * FROM biz_task_assignment WHERE company_id=? AND task_id=? AND user_id=? FOR UPDATE",c,l.get("task_id"),in.userId());long id;
 if(previous.isEmpty()){db.update("INSERT INTO biz_task_assignment(company_id,task_id,signup_id,project_id,user_id,assigned_quantity,due_date,status,create_by) VALUES(?,?,?,?,?,?,?,'PENDING',?)",c,l.get("task_id"),in.signupId(),pid,in.userId(),in.quantity(),in.dueDate(),SecurityUtils.getUsername());id=db.queryForObject("SELECT id FROM biz_task_assignment WHERE company_id=? AND task_id=? AND user_id=?",Long.class,c,l.get("task_id"),in.userId());}else{var old=previous.get(0);id=((Number)old.get("id")).longValue();if(!"CANCELLED".equals(old.get("status"))||db.queryForObject("SELECT COUNT(*) FROM biz_work_record WHERE assignment_id=?",Long.class,id)>0)throw new ServiceException("该员工已有该任务分配",409);db.update("UPDATE biz_task_assignment SET status='PENDING',assigned_quantity=?,due_date=?,project_id=?,version=version+1 WHERE id=? AND company_id=?",in.quantity(),in.dueDate(),pid,id,c);}
 event(c,pid,id,null,"ASSIGN","",in,"分配任务");return id;}
 @Transactional public void cancel(long id,Integer v,String opinion){long c=own("manage");lock(c);var a=assignment(c,id,true);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));version(a,v);note(opinion);if(!"PENDING".equals(a.get("status")))throw new ServiceException("仅待领取分配可取消",409);db.update("UPDATE biz_task_assignment SET status='CANCELLED',version=version+1 WHERE id=? AND company_id=?",id,c);event(c,p,id,null,"CANCEL",a,"CANCELLED",opinion);}
 public List<Map<String,Object>> mine(){long c=own("work");return db.queryForList("SELECT a.*,t.title,t.unit,t.start_date,t.end_date FROM biz_task_assignment a JOIN biz_task t ON t.id=a.task_id WHERE a.company_id=? AND a.user_id=? AND a.project_id IS NOT NULL ORDER BY a.id DESC LIMIT 500",c,uid());}
 @Transactional public void claim(long id,Integer v){long c=own("work");lock(c);activeUser(c,uid());var a=assignment(c,id,true);mine(a);version(a,v);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));if(!"PENDING".equals(a.get("status")))throw new ServiceException("任务不在待领取状态",409);db.update("UPDATE biz_task_assignment SET status='EXECUTING',version=version+1,update_by=? WHERE id=? AND company_id=?",SecurityUtils.getUsername(),id,c);event(c,p,id,null,"CLAIM",a,"EXECUTING","员工领取任务");}
 public Map<String,Object> personal(long id){long c=own("work");var a=assignment(c,id,false);mine(a);a.put("records",db.queryForList("SELECT * FROM biz_work_record WHERE company_id=? AND assignment_id=? AND user_id=? ORDER BY work_date DESC",c,id,uid()));a.put("events",db.queryForList("SELECT * FROM biz_execution_event WHERE company_id=? AND assignment_id=? ORDER BY id DESC LIMIT 500",c,id));return a;}
 public record Work(LocalDate workDate,BigDecimal quantity,String remark,Integer version){}
 BigDecimal reserved(long c,long a,long exclude){return sum(db.queryForList("SELECT quantity FROM biz_work_record WHERE company_id=? AND assignment_id=? AND id<>? AND status NOT IN ('RETURNED','VOID') FOR UPDATE",c,a,exclude),"quantity");}
 @Transactional public long save(long aid,Long id,Work in){long c=own("work");lock(c);activeUser(c,uid());var a=assignment(c,aid,true);mine(a);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));if(!"EXECUTING".equals(a.get("status")))throw new ServiceException("须先领取任务且任务不可已完成",409);amount(in.quantity());var dates=db.queryForMap("SELECT start_date,end_date FROM biz_task WHERE id=?",a.get("task_id"));if(in.workDate()==null||in.workDate().isAfter(LocalDate.now(ZONE))||in.workDate().isBefore(((java.sql.Date)dates.get("start_date")).toLocalDate())||in.workDate().isAfter(((java.sql.Date)dates.get("end_date")).toLocalDate())||in.workDate().isAfter(((java.sql.Date)a.get("due_date")).toLocalDate())||in.remark()!=null&&in.remark().length()>500)throw new ServiceException("工作日期或备注无效",400);if(reserved(c,aid,id==null?0:id).add(in.quantity()).compareTo((BigDecimal)a.get("assigned_quantity"))>0)throw new ServiceException("上报累计量超过分配量",409);
 long rid;if(id==null){if(!db.queryForList("SELECT id FROM biz_work_record WHERE assignment_id=? AND user_id=? AND work_date=? FOR UPDATE",aid,uid(),in.workDate()).isEmpty())throw new ServiceException("同任务同日期已有记录，请修改原记录",409);db.update("INSERT INTO biz_work_record(company_id,assignment_id,user_id,work_date,quantity,status,remark,create_by) VALUES(?,?,?,?,?,'DRAFT',?,?)",c,aid,uid(),in.workDate(),in.quantity(),in.remark()==null?"":in.remark(),SecurityUtils.getUsername());rid=db.queryForObject("SELECT id FROM biz_work_record WHERE assignment_id=? AND work_date=? AND user_id=?",Long.class,aid,in.workDate(),uid());}else{var old=work(c,id,true);if(((Number)old.get("assignment_id")).longValue()!=aid||!Set.of("DRAFT","RETURNED","VOID").contains(old.get("status")))throw new ServiceException("记录状态或分配不允许修改",409);version(old,in.version());if(!in.workDate().equals(((java.sql.Date)old.get("work_date")).toLocalDate()))throw new ServiceException("工作日期不可更换",400);db.update("UPDATE biz_work_record SET quantity=?,remark=?,status=IF(status='VOID','RETURNED',status),version=version+1,update_by=? WHERE id=? AND company_id=?",in.quantity(),in.remark()==null?"":in.remark(),SecurityUtils.getUsername(),id,c);rid=id;}
 event(c,p,aid,rid,"WORK_SAVE","",in,"工作量保存，尚未计入进度");return rid;}
 Map<String,Object> work(long c,long id,boolean lock){var rows=db.queryForList("SELECT * FROM biz_work_record WHERE company_id=? AND id=?"+(lock?" FOR UPDATE":""),c,id);if(rows.isEmpty())throw new ServiceException("工作记录不存在或无权访问",404);return rows.get(0);}
 @Transactional public void submit(long id,Integer v){long c=own("work");lock(c);activeUser(c,uid());var w=work(c,id,true);var a=assignment(c,((Number)w.get("assignment_id")).longValue(),true);mine(a);version(w,v);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));if(!"EXECUTING".equals(a.get("status"))||!Set.of("DRAFT","RETURNED").contains(w.get("status")))throw new ServiceException("记录或任务状态不可提交",409);if(reserved(c,((Number)a.get("id")).longValue(),id).add((BigDecimal)w.get("quantity")).compareTo((BigDecimal)a.get("assigned_quantity"))>0)throw new ServiceException("累计量超过分配量",409);db.update("UPDATE biz_work_record SET round_no=round_no+IF(status='RETURNED',1,0),status='SUBMITTED',version=version+1 WHERE id=? AND company_id=?",id,c);event(c,p,((Number)a.get("id")).longValue(),id,"WORK_SUBMIT",w,"SUBMITTED","员工提交工作量");}
 @Transactional public void review(long id,Integer v,boolean approve,String opinion){long c=own("manage");lock(c);note(opinion);var w=work(c,id,true);version(w,v);var a=assignment(c,((Number)w.get("assignment_id")).longValue(),true);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));if(!"EXECUTING".equals(a.get("status"))||!"SUBMITTED".equals(w.get("status")))throw new ServiceException("状态不允许审核",409);if(((Number)w.get("user_id")).longValue()==uid())throw new AccessDeniedException("不得审核本人工作量");String status=approve?"CONFIRMED":"RETURNED";db.update("UPDATE biz_work_record SET status=?,version=version+1 WHERE id=? AND company_id=?",status,id,c);db.update("INSERT INTO biz_audit_record(company_id,business_type,business_id,round_no,applicant_id,reviewer_id,from_status,to_status,opinion,status) VALUES(?,'work_record',?,?,?,?,'SUBMITTED',?,?,'RECORDED')",c,id,w.get("round_no"),w.get("user_id"),uid(),status,opinion);event(c,p,((Number)a.get("id")).longValue(),id,"WORK_REVIEW",w,status,opinion);}
 @Transactional public void reopen(long id,Integer v,String opinion){long c=own("manage");lock(c);note(opinion);var w=work(c,id,true);version(w,v);var a=assignment(c,((Number)w.get("assignment_id")).longValue(),true);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));if(!"EXECUTING".equals(a.get("status"))||!"CONFIRMED".equals(w.get("status")))throw new ServiceException("仅执行中的已确认记录可退回更正",409);db.update("UPDATE biz_work_record SET status='RETURNED',version=version+1 WHERE id=? AND company_id=?",id,c);event(c,p,((Number)a.get("id")).longValue(),id,"CORRECTION",w,"RETURNED",opinion);}
 @Transactional public void voidWork(long id,Integer v,String opinion){long c=own("work");lock(c);note(opinion);var w=work(c,id,true);var a=assignment(c,((Number)w.get("assignment_id")).longValue(),true);mine(a);version(w,v);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));if(!"EXECUTING".equals(a.get("status"))||!Set.of("DRAFT","RETURNED").contains(w.get("status")))throw new ServiceException("仅草稿/退回记录可作废",409);db.update("UPDATE biz_work_record SET status='VOID',version=version+1 WHERE id=? AND company_id=?",id,c);event(c,p,((Number)a.get("id")).longValue(),id,"VOID",w,"VOID",opinion);}
 @Transactional public void finish(long id,Integer v){long c=own("work");lock(c);var a=assignment(c,id,true);mine(a);version(a,v);long p=((Number)a.get("project_id")).longValue();writable(project(c,p,true));var records=db.queryForList("SELECT * FROM biz_work_record WHERE company_id=? AND assignment_id=? FOR UPDATE",c,id);BigDecimal total=BigDecimal.ZERO;for(var w:records)if("CONFIRMED".equals(w.get("status")))total=total.add((BigDecimal)w.get("quantity"));else if(!"VOID".equals(w.get("status")))throw new ServiceException("尚有未确认工作量",409);if(!"EXECUTING".equals(a.get("status"))||total.compareTo((BigDecimal)a.get("assigned_quantity"))!=0)throw new ServiceException("已确认量尚未达到分配量",409);db.update("UPDATE biz_task_assignment SET status='COMPLETED',version=version+1 WHERE id=? AND company_id=?",id,c);event(c,p,id,null,"FINISH",a,"COMPLETED","员工完成分配任务");}
 @Transactional public void complete(long id,Integer v,String opinion,boolean archive){long c=own("manage");lock(c);note(opinion);var p=project(c,id,true);version(p,v);if(archive){if(!"COMPLETED".equals(p.get("status")))throw new ServiceException("项目须先完成确认",409);}else{writable(p);var progress=progress(c,id,true);if(((BigDecimal)progress.get("totalQuantity")).signum()<=0||((BigDecimal)progress.get("totalQuantity")).compareTo((BigDecimal)progress.get("confirmedQuantity"))!=0||((List<Map<String,Object>>)progress.get("assignments")).stream().anyMatch(a->!Set.of("COMPLETED","CANCELLED").contains(a.get("status"))))throw new ServiceException("工作量或成员任务尚未全部完成",409);db.update("UPDATE biz_task_signup s JOIN biz_project_task l ON l.signup_id=s.id AND l.company_id=s.company_id SET s.execution_status='COMPLETED',s.version=s.version+1 WHERE l.project_id=? AND l.company_id=?",id,c);}
 String status=archive?"ARCHIVED":"COMPLETED";db.update("UPDATE biz_project SET status=?,version=version+1,update_by=? WHERE id=? AND company_id=?",status,SecurityUtils.getUsername(),id,c);event(c,id,null,null,status,p,status,opinion);}
 @Transactional public void completeTask(long id,Integer v,String opinion){note(opinion);var t=tasks.task(id,true);tasks.owner(t);version(t,v);if(!Set.of("PUBLISHED","CLOSED","EXECUTING").contains(t.get("status")))throw new ServiceException("任务状态不可确认完成",409);var signups=db.queryForList("SELECT * FROM biz_task_signup WHERE task_id=? AND status IN ('PENDING','APPROVED') FOR UPDATE",id);BigDecimal total=BigDecimal.ZERO;for(var s:signups){if(!"APPROVED".equals(s.get("status"))||!"COMPLETED".equals(s.get("execution_status")))throw new ServiceException("尚有待审核或未完成的企业报名",409);total=total.add((BigDecimal)s.get("promised_quantity"));}if(total.compareTo((BigDecimal)t.get("target_quantity"))!=0||total.signum()<=0)throw new ServiceException("已完成企业承诺量未达到任务目标",409);db.update("UPDATE biz_task SET status='COMPLETED',version=version+1 WHERE id=?",id);tasks.event(id,null,(Long)t.get("company_id"),"COMPLETE",opinion);}
}
